/* Месяцеслов «Православных» — 10.
   Каждый святой имеет краткое описание; lifeId — полное житие (src/lib/content/lives.ts). */

import type { SaintRec } from "./types";

export const M10: SaintRec[] = [
  { key: "10-01", name: "Попразднство Воздвижения Честного и Животворящего Креста Господня", kind: "feast", desc: "Битбунов Г.С. Воздвижение Креста Господня. Событие праздника и его эортологическая динамика В этот день православные христиане вспоминают два события. Как говорит Священное Предание, Крест был найден в 326 году в Иерусалиме." },
  { key: "10-01", name: "Прп. Евмения, епископа Гортинского", kind: "saint", desc: "Прп. Евмений, епископ Гортинский (Крит), прославился добродетельной жизнью и милосердием. Ревностно защищал православную веру от ереси монофелитов, за что был сослан в Фиваиду, где скончался в VII веке." },
  { key: "10-01", name: "прп. Евфросинии, в миру Феодулии, Суздальской", kind: "saint", desc: "Прп. Евфросиния Суздальская (1212–1250), княжна Черниговская, приняла постриг после внезапной кончины жениха. Прославилась аскетическими подвигами и даром прозорливости." },
  { key: "10-01", name: "прп. Илариона Оптинского", kind: "saint", desc: "Прп. Иларион (в миру Родион Пономарев, 1805-1873) родился в благочестивой семье воронежского портного. Тихий и кроткий, он с юности стремился к монашеству." },
  { key: "10-01", name: "Мц. Ариадны Промисской (Фригийской)", kind: "saint", desc: "Св. мц. Ариадна, рабыня из Фригии, пострадала при императоре Адриане (II в.). Отказавшись участвовать в языческом жертвоприношении, была жестоко истязаема: её подвешивали и рвали тело железными крюками, затем бросили в темницу." },
  { key: "10-01", name: "мч. Кастора", kind: "saint", desc: "Немного нам известно о жизни и смерти св. Кастора. Святой принадлежит к многочисленной группе святых, о которых знаем лишь одно имя и то, что святой мученик Кастор принял мученическую кончину за открытое и смелое исповедание веры во имя и славу Христа." },
  { key: "10-01", name: "Собор новомучеников и исповедников земли Владимирской", kind: "feast", desc: "По благословению Патриарха Московского и всея Руси Кирилла установлен Собор новомучеников и исповедников земли Владимирской. Празднование Собора будет отмечаться 1 октября, в день памяти священномученика Константина Твердислова." },
  { key: "10-01", name: "Алексия Кузнецова", kind: "saint", desc: "Сщмч. Алексий Кузнецов (1873–1918) служил священником в Иоанно-Богословском храме Верхне-Салдинского завода на Урале. Активно занимался миссионерской деятельностью, противостоя расколу и сектантству." },
  { key: "10-01", name: "Петра Дьяконова", kind: "saint", desc: "Сщмч. Петр Дьяконов (1866–1918) служил настоятелем Иоанно-Богословского храма в Верхне-Салдинском заводе на Урале. Прославился как талантливый регент и миссионер." },
  { key: "10-01", name: "Амфилохия (Скворцова), епископа Красноярского", kind: "saint", desc: "Сщмч. Амфилохий (Скворцов), епископ Красноярский (1885–1937), был выдающимся миссионером, учёным-монголоведом и ревностным защитником православия. После революции отказался от компромиссов с обновленцами и советской властью." },
  { key: "10-01", name: "Иоанна Васильева", kind: "saint", desc: "Сщмч. Иоанн Васильев родился в 1876 году в крестьянской семье. Окончив Тверскую духовную семинарию, он был рукоположен в священники и служил в селе Осипово, а с 1928 года ‒ в селе Таложня, где активно возрождал духовную жизнь." },
  { key: "10-01", name: "Бориса Боголепова", kind: "saint", desc: "Сщмч. Борис Боголепов (1889-1937) служил священником в селе Коробино Тверской области. В 1937 году власти неоднократно привлекали его к суду за отказ платить непосильные налоги и за совершение церковных треб без справок от сельсовета." },
  { key: "10-01", name: "Михаила Скобелева", kind: "saint", desc: "Сщмч. Михаил Скобелев, священник, родился в 1887 году в Тверской губернии. Служил в селе Рамешки. В 1929 году был арестован за неуплату налогов и провел несколько лет в лагере и ссылке." },
  { key: "10-01", name: "Владимира Чекалова", kind: "saint", desc: "Сщмч. Владимир Чекалов родился в 1880 году. Окончив семинарию, он служил священником в храмах Тверской епархии. В 1933 году был арестован за критику советской власти и колхозной системы, вызванную непосильными налогами, и осужден на три года лагерей." },
  { key: "10-02", name: "Попразднство Воздвижения Честного и Животворящего Креста Господня", kind: "feast", desc: "Битбунов Г.С. Воздвижение Креста Господня. Событие праздника и его эортологическая динамика В этот день православные христиане вспоминают два события. Как говорит Священное Предание, Крест был найден в 326 году в Иерусалиме." },
  { key: "10-02", name: "Феодора Ростиславича Черного, Смоленского (1299), и чад его", kind: "saint", desc: "Св. блгв. князь Феодор Смоленский и Ярославский, прозванный Черным, правил в XIII веке. После смерти первой супруги долгое время провел в Золотой Орде, где женился на дочери хана, принявшей крещение, способствуя укреплению мира и распространению православия." },
  { key: "10-02", name: "Давида", kind: "saint", desc: "Св. блгв. князь Давид Ярославский (†1321) был сыном знаменитого св. князя Феодора Смоленского и правил в Ярославле после его смерти. Он разделил своё княжество между двумя сыновьями, Василием и Михаилом, положив начало нескольким знатным княжеским родам." },
  { key: "10-02", name: "Константина, Ярославских чудотворцев", kind: "saint", desc: "Св. блгв. князь Константин Ярославский был младшим сыном св. князя Феодора Смоленского, рожденным в Орде от его брака с ханской дочерью. Точных данных о его жизни и княжении не сохранилось, известно лишь, что он скончался раньше своего отца." },
  { key: "10-02", name: "прп. Алексия Зосимовского (Соловьева)", kind: "saint", desc: "Прп. Алексий Зосимовский (1846–1928), в миру Фёдор Соловьёв, был сыном московского священника. Пройдя путь приходского диакона и священника, он овдовел и принял монашеский постриг в Зосимовой пустыни." },
  { key: "10-02", name: "Прмч. Зосимы пустынника", kind: "saint", desc: "Прмч. Зосима, живший в IV веке, был христианином, удалившимся от мира в пустыню. Однажды его обнаружил правитель Киликии Дометиан, увидев, как старец мирно беседует с дикими зверями." },
  { key: "10-02", name: "блгв. вел. кн. Игоря (во Святом Крещении Георгия) Черниговского и Киевского", kind: "saint", desc: "Св. блгв. кн. Игорь Черниговский (†1147) стал жертвой княжеских междоусобиц. После краткого киевского княжения был свергнут, пострижен в схиму, но через год убит восставшими киевлянами прямо в храме во время молитвы перед иконой Богородицы (впоследствии названной Игоревской)." },
  { key: "10-02", name: "Сщмч. Константина (Голубева), Богородского, пресвитера", kind: "saint", desc: "Сщмч. Константин Голубев был известным миссионером, боровшимся с расколом в Саратовской губернии, где благодаря его трудам к Православной Церкви присоединились сотни людей." },
  { key: "10-02", name: "сщмч. Николая Искровского, пресвитера", kind: "saint", desc: "Сщмч. Николай Искровский служил священником в селе Искровка, храм для которого был построен по личной инициативе и на средства императора Николая II. Отец Николай был известен своей прозорливостью, даром исцелений и глубокой молитвенностью." },
  { key: "10-02", name: "сщмч. Константина Богословского, пресвитера", kind: "saint", desc: "Сщмч. протоиерей Константин Богословский (1871–1937) окончил Казанскую духовную академию и большую часть жизни посвятил преподаванию. После революции он участвовал в работе Всероссийского Поместного Собора 1917–1918 годов." },
  { key: "10-02", name: "сщмч. Нила Смирнова, пресвитера", kind: "saint", desc: "Сщмч. Нил Смирнов родился в 1881 году в семье учителя. До 40 лет работал на железной дороге, а в 1921 году был рукоположен в священника. Служил в московских храмах." },
  { key: "10-02", name: "прмц. Марии Мамонтовой-Шашиной, послушницы", kind: "saint", desc: "Прмц. Мария (Мамонтова-Шашина) родилась в 1890 году в крестьянской семье. В 1914 году ушла в Колычевский монастырь, но после его закрытия в 1920 году вернулась в родное село." },
  { key: "10-02", name: "сщмч. Никандра Гривского, пресвитера", kind: "saint", desc: "Сщмч. Никандр Гривский (1880-1939) служил в погосте Почеп Псковской губернии. В 1930 году арестован за противодействие хлебозаготовкам и приговорен к 10 годам лагерей." },
  { key: "10-03", name: "Попразднство Воздвижения Честного и Животворящего Креста Господня", kind: "feast", desc: "Битбунов Г.С. Воздвижение Креста Господня. Событие праздника и его эортологическая динамика В этот день православные христиане вспоминают два события. Как говорит Священное Предание, Крест был найден в 326 году в Иерусалиме." },
  { key: "10-03", name: "Прп. и блгв. кн. Олега Брянского", kind: "saint", desc: "Св. блгв. князь Олег (в иночестве Василий) Брянский, внук мученика Михаила Черниговского, первоначально участвовал в ратных делах. Однако, после 1274 года, отказавшись от княжеской власти, он основал на свои средства Брянский Петропавловский монастырь и принял там постриг." },
  { key: "10-03", name: "Собор святых Брянской митрополии", kind: "feast", desc: "Празднование Собора святых Брянской митрополии установлено 5 декабря 2003 г. по благословению Патриарха Алексия II. Дата празднования – 3 октября. Поименный список Собора утвержден Священным Синодом Русской Православной Церкви 16 мая 2023 года (журнал № 31)." },
  { key: "10-03", name: "Феоктиста Смельницкого", kind: "saint", desc: "Сщмч. Феоктист Смельницкий родился в 1874 году в семье псаломщика. Окончив духовную семинарию, он служил священником в различных приходах Черниговской губернии, был законоучителем." },
  { key: "10-03", name: "Александра Тетюева", kind: "saint", desc: "Сщмч. Александр Тетюев родился в 1879 году в семье потомственных священников Пермской губернии. В юности был отправлен отцом в Соликамский монастырь, где стал послушником." },
  { key: "10-04", name: "Отдание праздника Воздвижения Животворящего Креста Господня", kind: "feast", desc: "Битбунов Г.С. Воздвижение Креста Господня. Событие праздника и его эортологическая динамика В этот день православные христиане вспоминают два события. Как говорит Священное Предание, Крест был найден в 326 году в Иерусалиме." },
  { key: "10-04", name: "Ап. от 70-ти Кодрата", kind: "saint", desc: "Сщмч. Кодрат был апостолом от 70-ти, епископом Афинским и Магнезийским. Он проповедовал Евангелие в Греции, обращая многих язычников ко Христу. За свою ревность о вере он подвергся гонениям: разъяренная толпа пыталась побить его камнями, после чего он был заключен в темницу, где скончался от голода." },
  { key: "10-04", name: "Обретение мощей свт. Димитрия, митрополита Ростовского", kind: "saint", desc: "Свт. Димитрий Ростовский (1651–1709), в миру Даниил Туптало, ‒ выдающийся церковный деятель, проповедник и агиограф. Приняв монашество, он более 20 лет посвятил созданию Четьих-Миней ‒ сборника житий святых, ставшего главным трудом его жизни." },
  { key: "10-04", name: "Прп. Даниила Шужгорского", kind: "saint", desc: "Прп. Даниил Шужгорский, подвизавшийся в XVI веке, был уроженцем Московских земель. Он принял постриг в Комельском монастыре, но стремясь к уединению, удалился в глухие леса Белозерского края на гору Шужгору." },
  { key: "10-04", name: "прп. Иосифа Заоникиевского (Вологодского)", kind: "saint", desc: "Прп. Иосиф Заоникиевский, в миру крестьянин Иларион, жил в Вологодской губернии. Страдая глазной болезнью, он усердно молился и в 1588 году по откровению обрёл в лесу чудотворную икону Божией Матери, получив исцеление." },
  { key: "10-04", name: "Исаакия", kind: "saint", desc: "Свтт. Исакий и Мелетий были епископами Кипрскими, известными своей благочестивой жизнью и ревностным служением Церкви. Они неустанно проповедовали слово Божие, наставляя народ в христианских добродетелях." },
  { key: "10-04", name: "Мелетия, епископов Кипрских", kind: "saint", desc: "Свтт. Исакий и Мелетий были епископами Кипрскими, известными своей благочестивой жизнью и ревностным служением Церкви. Они неустанно проповедовали слово Божие, наставляя народ в христианских добродетелях." },
  { key: "10-04", name: "свт. Никодима (Милаша), епископа Далматинского и Истрийского", kind: "saint", desc: "Святитель Никодим (Милаш, 1845-1915), епископ Далматинский и Истрийский, в годы своего пребывания на Далматинской кафедре (Австро-Венгерская Империя) в 1890-1912 гг." },
  { key: "10-04", name: "Собор святых Кубанской митрополии", kind: "feast", desc: "Празднование Собора и поименный список установлены решением Священного Синода от 16 мая 2023 года. Днесь ликовствует земля Кубанская, / прославляющи святители, преподобныя и новомученики своя, / во благочестии подвизавшияся и страданьми украсившияся,/ и небесныя венцы от Господа приемшия." },
  { key: "10-04", name: "Собор святых, в земле Германской просиявших", kind: "feast", desc: "Празднование установлено Священным Синодом Русской Православной Церкви на заседании 24 августа 2023 года. Иже в земли Германской прославльшиися/ святитилие, мученицы, преподобнии, праведнии и вси святии,/ верою, подвиги благочестия, любовию" },
  { key: "10-04", name: "Александра Федосеева", kind: "saint", desc: "Сщмч. Александр Федосеев служил священником на заводе Майкор в Пермской губернии. Во время массовых репрессий 1918 года был расстрелян красноармейцами." },
  { key: "10-04", name: "Алексия Стабникова", kind: "saint", desc: "Сщмч. Алексий Стабников, настоятель собора в Юговском заводе близ Перми, был убит красноармейцами 4 октября 1918 года во время массовых репрессий в Пермском крае." },
  { key: "10-04", name: "Константина Широкинского", kind: "saint", desc: "Сщмч. Константин Широкинский, служивший в Слудской Свято-Троицкой церкви Перми, был арестован в 1918 году по обвинению в монархических и контрреволюционных взглядах." },
  { key: "10-04", name: "Иоанна Флерова", kind: "saint", desc: "Сщмч. Иоанн Флеров был строителем и первым настоятелем храма Архангела Михаила в селе Семьяны Нижегородской губернии, освящённого незадолго до революции." },
  { key: "10-05", name: "Прор. Ионы", kind: "saint", desc: "Пророк Иона, живший в VIII веке до Р.Х., был сыном вдовы из Сарепты, которого в детстве воскресил пророк Илия. Когда Господь повелел ему проповедовать покаяние жителям Ниневии, Иона попытался скрыться, но был наказан: во время бури его бросили в море, и он был проглочен китом." },
  { key: "10-05", name: "сщмч. Фоки, епископа Синопского", kind: "saint", desc: "Сщмч. Фока (†117) – епископ Синопский, обратил многих язычников к вере Христовой. При императоре Траяне принял мученическую смерть: после жестоких пыток был заперт в раскаленной бане." },
  { key: "10-05", name: "прп. Ионы, пресвитера (IX), отца святых Феофана, творца канонов, и Феодора Начертанных", kind: "saint", desc: "Прп. Иона пресвитер, отец святых Феофана и Феодора Начертанных, жил в Палестине в конце VIII ‒ начале IX века. После кончины супруги он удалился в Лавру прп." },
  { key: "10-05", name: "блж. Параскевы Дивеевской", kind: "saint", desc: "Блж. Параскева (в миру Ирина) родилась в начале XIX века в крепостной семье в Тамбовской губернии. После замужества и смерти супруга, пережив несправедливое обвинение в краже и жестокое наказание, она отправилась в Киев на богомолье, где духовно преобразилась." },
  { key: "10-05", name: "Прп. Ионы Яшезерского", kind: "saint", desc: "Прп. Иона Яшезерский, уроженец села Шокша, основал в 80-х годах XVI века Благовещенский монастырь. Слава о его святости привлекала паломников, способствуя росту монастыря." },
  { key: "10-05", name: "прп. Макария Жабынского, Белевского чудотворца", kind: "saint", desc: "Прп. Макарий Жабынский подвизался в начале XVII века, возродив разоренную литовцами Жабынскую пустынь. Он собрал братию, основал монастырь и стал его игуменом." },
  { key: "10-05", name: "Собор Тульских святых", kind: "feast", desc: "Празднование соборной памяти всех святых, в земле Тульской просиявших, было установлено 3 июня 1987 года по инициативе архиепископа Тульского и Белевского Максима (Крохи)." },
  { key: "10-05", name: "мч. Фоки Вертоградаря (Садовника)", kind: "saint", desc: "Св. мученик Фока жил в Синопе, содержа себя садоводством и помогая нуждающимся. Его благочестие вызывало уважение даже у язычников. Когда за ним послали воинов, он, не назвавшись, радушно их принял." },
  { key: "10-05", name: "прав. Петра Африканского, бывшего мытаря", kind: "saint", desc: "Св. Петр был главным сборщиком податей в Африке в царствование императора Юстиниана (527–565). Увидев во сне, что чашу его злых дел на Божественных весах перевешивает лишь кусок хлеба, брошенный нищему, он раскаялся." },
  { key: "10-05", name: "сщмч. Феодосия Бразского, митрополита (1694)", kind: "saint", desc: "Сщмч. Феодосий Бразский, молдавский митрополит XVII века, бесстрашно обличил господаря Думитрашку Кантакузино за жестокость и союз с татарами, за что был свергнут и заточен." },
  { key: "10-05", name: "Сщмч. Вениамина (Воскресенского), епископа Романовского, викария Ярославской епархии", kind: "saint", desc: "Сщмч. Вениамин (Воскресенский, 1871-1931) был хиротонисан во епископа Тутаевского, викария Ярославской епархии в 1921 году. Ревностный пастырь, он активно противостоял обновленческому расколу, за что был арестован в 1922 году и осужден на семь лет." },
  { key: "10-06", name: "Зачатие честного, славного Пророка, Предтечи и Крестителя Господня Иоанна", kind: "feast", desc: "Пророк Иоанн Креститель – после Девы Марии самый чтимый святой. С именем Иоанна Предтечи связано семь праздников (по новому стилю): Пророк Иоанн Креститель был сыном священника Захарии (из рода Аарона) и праведной Елизаветы (из рода царя Давида)." },
  { key: "10-06", name: "прославление свт. Иннокентия, митрополита Московского", kind: "saint", desc: "Свт. Иннокентий (в миру Иван Попов-Вениаминов), митрополит Московский (1797-1879) – выдающийся миссионер, просветитель народов Америки и Сибири. За 45 лет он крестил десятки тысяч человек, строил храмы и школы, изучал языки, быт и нравы местных народов." },
  { key: "10-06", name: "мц. Раисы (Ираиды) девы", kind: "saint", desc: "Св. мц. Ираида Александрийская, увидев корабль с заключёнными в оковы христианами, добровольно присоединилась к ним. Когда судно прибыло в египетский город Антиполь, она первая приняла жестокие мучения и была усечена мечом." },
  { key: "10-06", name: "Сщмч. Иоанна Панкратовича, пресвитера", kind: "saint", desc: "Сщмч. Иоанн Панкратович (1870–1937) был священником, служившим в Беларуси. После закрытия его храма в 1934 году он тайно совершал богослужения и требы." },
  { key: "10-06", name: "Словенская", year: "1635", kind: "saint", desc: "Чудотворная Словенская икона Божией Матери была чудесным образом обретена 15 мая 1628 года неким Титом Гавриловым, жителем деревни Шерстнево Галичского уезда Костромской губернии." },
  { key: "10-07", name: "Равноап. Феклы Иконийской, первомученицы", kind: "icon", desc: "Св. равноапостольная Фекла, первомученица из Иконии, была обращена проповедью апостола Павла и решила посвятить жизнь служению Богу, отказавшись от брака." },
  { key: "10-07", name: "Прп. Никандра пустынножителя, Псковского чудотворца", kind: "saint", desc: "Прп. Никандр Псковский (1507–1581) родился в крестьянской семье, с юности стремился к монашеству. Принял постриг в Крыпецком монастыре, но основную часть жизни провёл в уединённых подвигах в псковской пустыни." },
  { key: "10-07", name: "прмч. Галактиона Вологодского", kind: "saint", desc: "Прп. Галактион Вологодский (†1612) происходил из знатного рода князей Бельских, но после опалы отца жил в смирении, зарабатывая сапожным ремеслом. Приняв постриг, он стал затворником, поселившись в келье близ Вологды." },
  { key: "10-07", name: "прп. Коприя Палестинского", kind: "saint", desc: "Прп. Коприй Палестинский был найден новорождённым иноками обители прп. Феодосия Великого на куче навоза (по-гречески «коприа»), куда его бросила мать, спасаясь от врагов." },
  { key: "10-07", name: "блгв. кн. Владислава Сербского", kind: "saint", desc: "Св. Владислав Сербский, сын св. короля Стефана, правил с 1234 по 1242 год. Прославился милосердием и помощью нуждающимся. Основал монастырь в Милешеве, где провёл последние годы и был погребён после смерти." },
  { key: "10-07", name: "Сщмч. Василия Воскресенского, диакона", kind: "saint", desc: "Сщмч. Василий Воскресенский был диаконом Преображенского храма в городе Соликамск. В период массовых гонений 7 октября 1918 года он был расстрелян красноармейцами." },
  { key: "10-07", name: "Андрея Быстрова", kind: "saint", desc: "В июле 1937 года, на основании директивы Сталина о репрессиях против «кулаков», в Плоскошском районе Тверской области были арестованы священник Андрей Быстров и крестьянин Василий Виноградов." },
  { key: "10-07", name: "Павла Березина", kind: "saint", desc: "Сщмч. Павел Березин (1866-1937) был арестован в 1929 году за распространение религиозной литературы среди детей и критику безнравственных явлений в проповедях." },
  { key: "10-07", name: "прмч. Виталия (Кокорева), монаха", kind: "saint", desc: "Прмч. Виталий (Кокорев, 1890–1937) был монахом. Принял постриг в Ниловой пустыни, после её закрытия в 1928 году состоял в тайной монашеской общине. Был арестован, осуждён на 5 лет лагерей за «неуплату налогов» и сослан на Дальний Восток." },
  { key: "10-07", name: "Мирожская", year: "1198", kind: "saint", desc: "В Спасском Мирожском монастыре , основанном при устье реки Мирожи на Псковщине в 1156 году преподобным Авраамием Мирожским и святителем Нифонтом, архиепископом Новгородским, хранилась Мирожская чудотворная икона Божией Матери." },
  { key: "10-08", name: "Прп. Евфросинии Александрийской", kind: "saint", desc: "Прп. Евфросиния Александрийская (V век) родилась в знатной семье. После смерти матери её воспитывал благочестивый отец. Стремясь к монашеской жизни, она тайно приняла постриг и, переодевшись в мужскую одежду, под именем евнуха Измарагда поступила в тот самый мужской монастырь, который с детства посещала вместе с отцом." },
  { key: "10-08", name: "Преставление прп. Сергия, игумена Радонежского, чудотворца", kind: "saint", desc: "Прп. Сергий (в миру Варфоломей, 1314-1392), великий русский святой, был сыном ростовских бояр. С детства он стремился к учению, но грамота давалась с трудом, пока чудесная встреча с монахом не даровала ему разумение.", lifeId: "sergiy" },
  { key: "10-08", name: "Прп. Евфросинии, в миру Феодулии, Суздальской", kind: "saint", desc: "Прп. Евфросиния Суздальская (1212–1250), княжна Черниговская, приняла постриг после внезапной кончины жениха. Прославилась аскетическими подвигами и даром прозорливости." },
  { key: "10-08", name: "Перенесение мощей свт. Германа, архиепископа Казанского и Свияжского", kind: "saint", desc: "Свт. Герман Казанский (XVI в.), происходивший из боярского рода Полевых, начал монашеский путь в Иосифо-Волоколамском монастыре под руководством св. Гурия." },
  { key: "10-08", name: "прп. Досифеи затворницы, Киевской", kind: "saint", desc: "Прп. Досифея Киевская (в миру дворянка Дарья Тяпкина, 1721–1776) в юности тайно оставила дом ради монашеского подвига. Переодевшись в мужскую одежду и назвавшись Досифеем, около 17 лет провела в уединённой пещере на Китай-горе близ Киева, стяжав дар прозорливости." },
  { key: "10-08", name: "прмч. Пафнутия египтянина и с ним 546-ти мучеников", kind: "saint", desc: "Прмч. Пафнутий происходил из Египта и подвизался в пустыне. Во время гонений Диоклетиана он добровольно явился к правителю Ариану и исповедал христианскую веру." },
  { key: "10-08", name: "Св. Николая Розова, исп., пресвитера", kind: "saint", desc: "Сщисп. Николай Розов (1879–1941) родился в семье священника Ярославской губернии. Рукоположен в сан в 1902 году, совмещал служение с преподаванием в церковноприходской школе." },
  { key: "10-08", name: "Обретение мощей сщмчч. Александра Смирнова", kind: "saint", desc: "Сщмчч. Александр Смирнов и Феодор Лебедев были священниками соседних храмов в селе Вышегород Московской губернии. 14 ноября 1918 года они были арестованы карательным отрядом латышей." },
  { key: "10-08", name: "Феодора Лебедева", kind: "saint", desc: "Сщмчч. Александр Смирнов и Феодор Лебедев были священниками соседних храмов в селе Вышегород Московской губернии. 14 ноября 1918 года они были арестованы карательным отрядом латышей." },
  { key: "10-09", name: "Преставление апостола и евангелиста Ио а нна Богослова", year: "начало II", kind: "feast", desc: "Апостол Иоанн был особенно любим Спасителем за жертвенную любовь и девственную чистоту. После своего призвания апостол не расставался с Господом и был одним из трех учеников, которых Он особенно приблизил к Себе." },
  { key: "10-09", name: "свт. Тихона, патриарха Московского и всея Руси", kind: "saint", desc: "Свт. Тихон (Беллавин, 1865–1925) – одиннадцатый Патриарх Московский и всея Руси. Принял монашество в 1891 году. Управлял епархиями в Северной Америке, Ярославле, Вильно, проявляя особую заботу о пастве." },
  { key: "10-09", name: "Прп. Ефрема Перекомского, Новгородского, игумена", kind: "saint", desc: "Прп. Ефрем Перекомский родился в 1412 году в Тверской губернии. С юности вёл аскетическую жизнь, ушёл из дома в Калязинский монастырь, а затем перешёл в обитель прп." },
  { key: "10-09", name: "прав. Гедеона, судии Израильского", kind: "saint", desc: "Св. Гедеон – судия Израильский, избавитель израильского народа от мадианитян. Перед битвой Господь велел ему сократить войско с 32 тысяч до 300 человек, чтобы явить Свою силу." },
  { key: "10-09", name: "блгв. кн. Нягу Басарабского (1521)", kind: "saint", desc: "Блгв. князь Нягу Басарабский (ок. 1459–1521) – господарь Валахии с 1512 года. Восстановил традиции ктиторства господаря в важнейших монастырях страны. Был щедрым жертвователем на строительство храмов, поддерживал афонские монастыри." },
  { key: "10-09", name: "Афанасия Докукина", kind: "saint", desc: "Сщмч. Афанасий Докукин (1899–1937) родился в крестьянской семье в Курской губернии. С 1914 года служил псаломщиком, в 1923 году рукоположен в диакона, а в 1925 году – во священника." },
  { key: "10-09", name: "Александра Левитского", kind: "saint", desc: "Сщмч. Александр Левитский (1876–1937) родился в Москве. Окончив Московскую Духовную академию, преподавал в училищах. В 1904 году рукоположен в священника к Троицкому храму на Самотеке." },
  { key: "10-09", name: "Димитрия Розанова", kind: "saint", desc: "Сщмч. Димитрий Розанов (1890–1937) родился в Московской губернии. Окончил Вифанскую духовную семинарию, в 1914 году рукоположен во священника к Зосимовой пустыни." },
  { key: "10-09", name: "Иоанна Золотова", kind: "saint", desc: "Мч. Иоанн Золотов (1897–1937) жил в Москве, был глубоко верующим человеком. В 1932 году приютил у себя схимонахиню Александру (Червякову), оказывая ей регулярную материальную помощь." },
  { key: "10-09", name: "Николая Гусева", kind: "saint", desc: "Мч. Николай Гусев (1919–1937) родился в Москве, рано осиротел. В 1930-х годах, не имея постоянного жилья, построил шалаш в лесу под Реутовом, где жил отшельником, собирая утиль и грибы." },
  { key: "10-09", name: "сщмч. Владимира Вятского, пресвитера", kind: "saint", desc: "Сщмч. Владимир Вятский (1879–1938) родился в Ярославской губернии. Окончив сельскую школу, служил псаломщиком, затем был рукоположен в священника. В 1932 году арестован за «сокрытие церковных ценностей» и приговорён к трём годам ссылки." },
  { key: "10-09", name: "св. Димитрия Крючкова, исп., пресвитера", kind: "saint", desc: "Сщисп. Димитрий Крючков (1874–1952) родился в крестьянской семье. Служил псаломщиком, в 1915 году рукоположен в диакона, в 1920 году – в священника. В 1922 году арестован за чтение воззвания Патриарха Тихона и осуждён на 3 года лагерей." },
  { key: "10-10", name: "прп. Савватия Соловецкого", kind: "saint", desc: "Прп. Савватий Соловецкий – первоначальник Соловецкой обители. Принял постриг в Кирилло-Белоезерском монастыре, затем подвизался на Валааме, но, избегая мирской славы, отправился на необитаемый Соловецкий остров (1429 г.)." },
  { key: "10-10", name: "Аристарха", kind: "saint", desc: "Св. апостол от 70-ти Аристарх упоминается св. апостолом Павлом в Послании к Колоссянам (Кол.4:10) и к Филимону (Флм.1:24). Св. апостол Аристарх сопутствовал апостолу Павлу, а впоследствии был поставлен епископом в сирийский город Апамею." },
  { key: "10-10", name: "мц. Епихарии Римской", kind: "saint", desc: "Св. мц. Епихария пострадала в Риме во время гонений императора Диоклетиана (284–305). За исповедание христианской веры её подвергли жестоким пыткам: рвали тело железными крюками, избивали оловянными молотками, но по её молитве Ангел поразил мучителей." },
  { key: "10-10", name: "прп. Игнатия Глубокореченского (Каппадокийского), игумена", kind: "saint", desc: "Прп. Игнатий Глубокореченский (X век) жил в Каппадокии и с юности посвятил себя Богу. Приняв монашество, он был рукоположен в сан пресвитера, а затем стал игуменом обители Спаса, известной как «Глубокие реки», близ Константинополя." },
  { key: "10-10", name: "сщмч. Анфима Иверянина, митрополита Валашского (1716)", kind: "saint", desc: "Сщмч. Анфим Иверянин (ок. 1650–1716) родился в Грузии. Попав в юности в турецкий плен, выучил несколько языков. Был выкуплен и приглашён в Валахию, где принял монашество." },
  { key: "10-10", name: "Сщмч. Петра, митрополита Крутицкого", kind: "saint", desc: "Сщмч. Петр (Полянский; 1862–1937) – митрополит Крутицкий, Местоблюститель Патриаршего Престола после кончины Патриарха Тихона (1925). Ближайший сподвижник Патриарха, он отказался идти на компромиссы с советской властью и отречься от первосвятительского служения." },
  { key: "10-10", name: "сщмч. Димитрия Шишокина, пресвитера", kind: "saint", desc: "Сщмч. Димитрий Шишокин (1880–1918) – священник тюремной церкви в Казани. Был арестован в 1918 году по ложному доносу за «агитацию против советской власти» после проповеди." },
  { key: "10-10", name: "Германа (Косолапова), епископа Вольского,", kind: "saint", desc: "Сщмч. Герман (Косолапов, 1882–1919) – епископ Вольский, викарий Саратовской епархии. Хиротонисан в 1918 году. В сентябре 1918 года арестован вместе с членами Епархиального совета за протест против арестов духовенства и организацию панихиды по царской семье." },
  { key: "10-10", name: "Михаила Платонова, пресвитера", kind: "saint", desc: "Сщмч. Михаил Платонов (1868–1919) – священник Саратовской епархии. В августе 1918 года после панихиды по убиенной царской семье и проповеди о гонениях на веру был арестован." },
  { key: "10-10", name: "сщмч. Феодора Богоявленского, пресвитера", kind: "saint", desc: "Сщмч. Феодор Богоявленский (1894–1937) родился в Рязанской губернии. Окончил Тамбовскую духовную семинарию. Служил в храмах Воронежской области. В 1930 году арестован за «антисоветскую агитацию» и осуждён на 3 года лагерей." },
  { key: "10-11", name: "Прп. Харитона Исповедника, епископа Иконийского", kind: "icon", desc: "Прп. Харитон Исповедник жил в III-IV веках. Он пострадал за веру в городе Иконии, где его пытали за отказ отречься от Христа. После окончания гонений его отпустили на свободу." },
  { key: "10-11", name: "Собор преподобных отцов Киево-Печерских, в Ближних пещерах (прп. Антония) почивающих", kind: "feast", desc: "Собор преподобных отцев Киево-Печерских, в Ближних (Антониевых) пещерах почивающих празднуется ныне 28 сентября (11 октября). Ранее эта общая память совершалась в первую субботу по отдании праздника Воздвижения, т.е." },
  { key: "10-11", name: "прп. Харитона Сянжемского, игумена", kind: "saint", desc: "Прпп. Евфимий и Харитон Сянжемские подвизались в XV – начале XVI века в Вологодских землях. Прп. Евфимий начал путь отшельника на берегу Кубенского озера, затем по просьбе прп." },
  { key: "10-11", name: "прп. Иродиона Илоезерского", kind: "saint", desc: "Прп. Иродион Илоезерский (XVI в.) был учеником прп. Корнилия Комельского. После смерти учителя он удалился на Илоозеро близ Белозерска, где основал пустынь с храмом в честь Рождества Пресвятой Богородицы." },
  { key: "10-11", name: "прор. Варуха", kind: "saint", desc: "Пророк Варух (VI в. до Р.Х.) был верным учеником и писцом пророка Иеремии. Он записывал и оглашал пророчества о грядущем вавилонском плене иудеев за их грехи, за что оба пророка подвергались гонениям." },
  { key: "10-11", name: "блгв. кн. Вячеслава Чешского", kind: "saint", desc: "Блгв. князь Вячеслав Чешский (†935) был внуком св. княгини Людмилы. Воспитанный в христианской вере, он получил блестящее образование. Став князем в 18 лет, правил мудро и справедливо, заботился о распространении христианства: строил храмы, выкупал детей из рабства для христианского воспитания." },
  { key: "10-11", name: "Собор святых Челябинской митрополии", kind: "feast", desc: "20 февраля 2020 года на заседании Архиерейского совета Челябинской митрополии было принято решение обратиться к патриарху Кириллу за благословением на установление празднования Собора святых Челябинской митрополии." },
  { key: "10-11", name: "Собор святых, в земле Испанской и Португальской просиявших", kind: "feast", desc: "Празднование Собора святых, в земле Испанской и Португальской просиявших установлено в воскресенье перед 12 октября. В состав Собора включены: Прикрепить к своему календарю Вебмастеру Обратная связь Ошибка? Выделение + кнопка! Если заметили" },
  { key: "10-11", name: "Обретение мощей прмц. вел. кн. Елисаветы", kind: "saint", desc: "Великая княгиня Елисавета Феодоровна, немецкая принцесса по рождению, приняла православие в 1891 г. После трагической гибели мужа от рук террориста полностью посвятила себя служению Богу и ближним, основав в Москве Марфо-Мариинскую обитель ‒ уникальный центр духовной и медицинской помощи." },
  { key: "10-11", name: "мц. Анны Лыкошиной", kind: "saint", desc: "Мц. Анна Лыкошина (1884–1925) родилась в Санкт-Петербурге, была глубоко верующей прихожанкой Сергиевского храма. После революции вошла в состав приходского совета для сохранения церковного имущества." },
  { key: "10-11", name: "прмч. Илариона (Громова), иеромонаха", kind: "saint", desc: "Прмч. Иларион (Громов; 1864–1937) родился в Тверской губернии. Принял постриг на Афоне, служил на подворье Афонского монастыря в Москве. После закрытия монастырей в 1922 году стал священником московского храма." },
  { key: "10-11", name: "прмц. Михаилы (Ивановой), схимонахини", kind: "saint", desc: "Прмч. Михаила (Марфа Иванова; 1867–1937), схимонахиня, родилась в Московской губернии. Приняла постриг в Казанском Головинском монастыре. После его закрытия в 1920-х годах осталась жить в селе Головино, работая в санатории." },
  { key: "10-11", name: "прмц. Татианы Чекмазовой, послушницы", kind: "saint", desc: "Послушница Татиана Чекмазова (1881–1942) расстреляна безбожниками 11 октября 1942 года. Причислена к лику святых в 2006 году. Преподобномученица Татиана (Чекмазова) родилась в 1881 году." },
  { key: "10-12", name: "Прп. Кириака отшельника, Палестинского", kind: "saint", desc: "Прп. Кириак Палестинский родился в Коринфе в V веке. В юности, впечатлённый словами Евангелия, тайно ушёл в Иерусалим. Стал монахом, учеником прпп. Евфимия Великого и Герасима Иорданского." },
  { key: "10-12", name: "Обретение мощей свт. Иоанна (Максимовича), архиепископа Шанхайского и Сан-Францисского", kind: "saint", desc: "Свт. Иоанн Шанхайский и Сан-Францисский (1896-1966) ‒ выдающийся архипастырь Церкви. Родился в Харьковской губернии, с детства отличался глубокой верой." },
  { key: "10-12", name: "прп. Феофана Милостивого", kind: "saint", desc: "Прп. Феофан Милостивый жил в сирийской Газе. Прославился необычайным милосердием: всё своё имение раздал нищим, оставшись в полной нищете. Был испытан тяжкой болезнью – его тело покрылось гнойными ранами и источало смрад, но святой всё терпел с благодарностью Богу." },
  { key: "10-12", name: "Сщмч. Иоанна (Поммера), архиепископа Рижского и Латвийского", kind: "saint", desc: "Сщмч. Иоанн (Поммер; 1876–1934) – архиепископ Рижский и Латвийский. Родился в латышской крестьянской семье. Окончил Киевскую духовную академию, принял монашество." },
  { key: "10-12", name: "сщмч. Михаила Красноцветова, пресвитера", kind: "saint", desc: "Сщмч. Михаил Красноцветов (1885–1937) родился в Калуге. Окончил юридический факультет. После гражданской войны пережил духовный перелом и в 1921 году принял священный сан." },
  { key: "10-13", name: "Сщмч. Григория, епископа, просветителя Великой Армении", kind: "saint", desc: "Сщмч. Григорий (ок. 257–335), просветитель и первый епископ Армении. Происходил из царского рода, но воспитывался в Кесарии Каппадокийской как христианин." },
  { key: "10-13", name: "прп. Григория Пельшемского, Вологодского чудотворца", kind: "saint", desc: "Прп. Григорий Пельшемский (ок. †1442) родился в Галиче в дворянской семье Лопотовых. Принял постриг в монастыре прп. Авраамия Галичского. Был игуменом Спасо-Песоцкого монастыря в Ростове, но, стремясь к уединению, удалился в вологодские леса." },
  { key: "10-13", name: "свт. Михаила, первого митрополита Киевского", kind: "saint", desc: "Свт. Михаил (X в.) ‒ киевский митрополит, присланный из Константинополя в 988 году для крещения Руси. Родом сириец, он активно распространял христианство: строил храмы, назначал священников, уничтожал языческих идолов." },
  { key: "10-13", name: "Сщмч. Прокопия Попова, пресвитера", kind: "saint", desc: "Сщмч. Прокопий Попов был настоятелем Троицкого храма в селе Шолга Вологодской губернии. 13 октября 1918 года, в разгар красного террора, карательный отряд арестовал его." },
  { key: "10-13", name: "Петра Соловьева", kind: "saint", desc: "Сщмч. Петр Соловьев родился в 1871 году в семье псаломщика Рязанской губернии. Окончив духовную семинарию, он был рукоположен в священника и всю жизнь прослужил настоятелем Казанского храма в селе Астанкино." },
  { key: "10-13", name: "Вячеслава Занкова", kind: "saint", desc: "Сщмч. Вячеслав Занков родился в 1892 году в дворянской семье. Окончив Московский университет, работал учителем. В 1920 году был рукоположен в священника и служил в московских храмах." },
  { key: "10-13", name: "Петра Пушкинского", kind: "saint", desc: "Сщмч. Петр Пушкинский родился в 1891 году в семье священника Московской губернии. Окончив Московскую духовную семинарию, служил настоятелем Ильинского храма в Верее." },
  { key: "10-13", name: "Симеона Лилеева", kind: "saint", desc: "Сщмч. Симеон Лилеев родился в 1873 году во Владимирской губернии. Большую часть жизни прослужил в Покровском храме села Заболотье Московской губернии. В 1936 году, когда власти закрыли храм, отец Симеон активно сопротивлялся этому, помогая верующим писать ходатайства о его открытии." },
  { key: "10-13", name: "Василия Гурьева", kind: "saint", desc: "Сщмч. Василий Гурьев родился в 1869 году в Московской губернии. Окончив духовную семинарию, он служил в Знаменской церкви села Кунцево. В 1929 году был арестован и приговорён к штрафу, а в 1932 году, после закрытия храма, перешёл в Спасскую церковь на Сетуни." },
  { key: "10-13", name: "Александра Орлова", kind: "saint", desc: "Сщмч. Александр Орлов родился в 1885 году в Московской губернии. Служил в Троицкой церкви села Троице-Голенищево. В 1932 году был арестован по ложному обвинению в антисоветской агитации и приговорён к трём годам лагерей на строительстве Беломорканала." },
  { key: "10-13", name: "Серафима Василенко, протодиакона", kind: "saint", desc: "Сщмч. протодиакон Серафим Василенко родился в 1905 году в Витебске. С юных лет служил Церкви: сначала псаломщиком, а в 1925 году был рукоположен во диакона." },
  { key: "10-13", name: "прмц. Александры (Червяковой), схимонахини", kind: "saint", desc: "Прмц. Александра (Червякова), родившаяся в 1873 году в Курске, приняла схиму в начале 1920-х годов. Несмотря на тяжёлую болезнь и почти полную слепоту, она стала известна в Москве как прозорливая старица, к которой за духовным советом и молитвой стекались многие верующие." },
  { key: "10-13", name: "Алексия Серебренникова", kind: "saint", desc: "Мч. Алексий Серебренников родился в 1882 году в Калужской губернии. До 1926 года служил в различных гражданских учреждениях, затем стал псаломщиком Христорождественского собора в Верее, а после его закрытия ‒ Богоявленской церкви." },
  { key: "10-13", name: "Матфея Соловьева", kind: "saint", desc: "Мч. Матфей Соловьев родился в 1868 году в Тверской губернии. До революции служил в армии и полиции. В 1929 году был избран председателем церковного совета и псаломщиком Благовещенской церкви села Георгие-Хотча, отказавшись вступить в колхоз." },
  { key: "10-14", name: "Покров Пресвятой Владычицы нашей Богородицы и Приснодевы Марии", kind: "feast", desc: "В Православной Церкви существует праздник Покрова Божией Матери, который основан на одном эпизоде с видением Богородицы в церкви из жития св. Андрея Юродивого: «Когда совершалось всенощное бдение в святой гробнице, находящейся во Влахернах, отправился туда и блаженный Андрей, творя то, что было у него в обычае." },
  { key: "10-14", name: "Ап. от 70-ти Анании", kind: "saint", desc: "Св. апостол Анания, один из семидесяти, был епископом Дамаска. По повелению Божию он крестил Савла, будущего апостола Павла. Анания бесстрашно проповедовал христианство в Дамаске, а затем в Елевферополе, где исцелял больных." },
  { key: "10-14", name: "прп. Романа Сладкопевца, диакона", kind: "saint", desc: "Прп. Роман Сладкопевец, византийский диакон и гимнограф, первоначально не обладал ни голосом, ни слухом. После насмешек клириков, вынудивших его петь на праздничной службе, он по молитве получил от Богородицы поэтический дар и прекрасный голос." },
  { key: "10-14", name: "прп. Саввы Вишерского, Новгородского", kind: "saint", desc: "Прп. Савва Вишерский родился в XV веке в Кашине в знатной боярской семье. Приняв постриг, он побывал на Афоне, а затем поселился отшельником на реке Вишере под Новгородом." },
  { key: "10-14", name: "Мч. Домнина Солунского", kind: "saint", desc: "Мч. Домнин Солунский пострадал в IV веке при императоре Максимиане Галерии. Он был схвачен за проповедь Евангелия, а после отказа принести жертву идолам подвергнут пыткам." },
  { key: "10-14", name: "прмч. Михаила, игумена Зовийского, и с ним 36-ти преподобномучеников", kind: "saint", desc: "Прмч. Михаил Зовийский, игумен монастыря Зовия близ Севастии Армянской, подвизался в VIII веке с 36 иноками. Во время нападения агарянского эмира Алима все они были захвачены." },
  { key: "10-14", name: "прп. Иоанна Кукузеля", kind: "saint", desc: "Прп. Иоанн Кукузель, болгарин по происхождению, в XII веке был первым придворным певцом в Константинополе. Однако, стремясь к духовной жизни, юноша тайно покинул двор и отправился на Афон." },
  { key: "10-14", name: "Празднование в честь Хитона Господня и Столпа Животворящего", kind: "saint", desc: "Празднование в честь Хитона Господня и Столпа Животворящего – храмовый праздник Мцхетского патриаршего собора в честь 12 святых апостолов, именуемого Свети-Цховели (что означает в переводе с грузинского «Животворящий Столп»)." },
  { key: "10-14", name: "Собор Молдавских святых", kind: "feast", desc: "Собор Молдавских святых – празднование Русской Православной Церкви в честь святых, просиявших в Молдавской земле, установленное в 2004 году согласно прошению митрополита Кишинёвского Владимира к патриарху Московскому и всея Руси Алексию II." },
  { key: "10-14", name: "Сщмч. Алексия Ставровского, пресвитера", kind: "saint", desc: "Сщмч. протоиерей Алексий Ставровский (1834–1918) родился в семье священника, окончил Санкт-Петербургскую духовную академию. Более 50 лет служил военным священником." },
  { key: "10-14", name: "сщмч. Михаила Вологодского, пресвитера", kind: "saint", desc: "Сщмч. Михаил Вологодский родился в 1888 году в семье священника Енисейской губернии. Окончив духовную семинарию, он был рукоположен в священника и служил в селе Агинское." },
  { key: "10-14", name: "Александра Агафонникова", kind: "saint", desc: "Сщмч. Александр Агафонников родился в 1881 году в Вятской губернии. Окончив духовную семинарию, он служил на различных приходах, преподавал Закон Божий." },
  { key: "10-14", name: "Георгия Архангельского", kind: "saint", desc: "Сщмч. Георгий Архангельский родился в 1872 году в Московской губернии. Приняв сан священника в 1917 году, он служил в храмах Наро-Фоминского района. В 1937 году, будучи настоятелем храма в селе Руднево, он объединил вокруг себя монахинь из закрытой Зосимовой пустыни, которые помогали в церкви и пели на клиросе.", lifeId: "georgiy" },
  { key: "10-14", name: "Николая Кулигина", kind: "saint", desc: "Сщмч. Николай Кулигин родился в 1870 году в Санкт-Петербургской губернии. Окончив духовную академию со степенью кандидата богословия, он был рукоположен в священника и с 1905 года до своего ареста служил настоятелем Покровской церкви в селе Рыбацкое под Петербургом." },
  { key: "10-15", name: "блж. Андрея, Христа ради юродивого, Константинопольского", kind: "saint", desc: "Блж. Андрей, Христа ради юродивый, жил в X веке в Константинополе. По откровению Ангела, принял подвиг юродства, добровольно избрав жизнь в нищете и презрении." },
  { key: "10-15", name: "прав. воина Феодора Ушакова", kind: "saint", desc: "Св. праведный воин Феодор Ушаков (1745-1817) ‒ великий русский адмирал, не потерпевший ни одного поражения в морских сражениях. После военной службы посвятил жизнь молитве и благотворительности, построил храм в деревне Алексеевке, помогал нуждающимся." },
  { key: "10-15", name: "Блгв. вел. кн. Анны Кашинской", kind: "saint", desc: "Св. блгв. княгиня Анна Кашинская (1280-1368), супруга тверского князя Михаила, пережила гибель мужа и сыновей в Орде, разорение Твери. Приняв монашество, стала образцом терпения и веры." },
  { key: "10-15", name: "прп. Кассиана грека, Угличского, Учемского, чудотворца", kind: "saint", desc: "Потомок греческих князей, прибыл в Москву с царевной Софией Палеолог (1478). Отказавшись от придворной жизни, ушёл в Ферапонтов монастырь, где принял постриг." },
  { key: "10-15", name: "Мц. Александры Булгаковой", kind: "saint", desc: "Мц. Александра Булгакова родилась в 1886 году в Тамбовской губернии. Глубоко верующая, она три года прожила в монастыре. В 1938 году, связав обострение болезни с участием в выборах безбожной власти, она решительно отказалась от голосования, публично разорвав приглашение и заявив о своей верности Богу." },
  { key: "10-16", name: "Прп. Дионисия Щепы, затворника Печерского, в Дальних пещерах, иеромонаха", kind: "saint", desc: "Прп. Дионисий Щепа, затворник Печерский, имел сан пресвитера. В 1463 году, во время пасхальной утрени, когда он кадил мощи святых в Антониевой пещере и возгласил: «Христос Воскресе!», от святых мощей раздался громогласный ответ: «Воистину Воскресе!»." },
  { key: "10-16", name: "прп. Иоанна Хозевита, епископа Кесарийского", kind: "saint", desc: "Прп. Иоанн Хозевит, епископ Кесарийский (VI в.), родился в египетских Фивах. С юности подвизался в Фиваидской пустыне. Был поставлен епископом Кесарии Палестинской, но, стремясь к уединению, оставил кафедру и удалился в Хузевскую пустыню близ Иерусалима." },
  { key: "10-16", name: "блж. Исихия Хоривита", kind: "saint", desc: "О блж. Исихии Хоривите (VI–VII вв.) рассказывается в «Лествице» прп. Иоанна Лествичника. В молодости он вёл жизнь нерадивую. После тяжёлой болезни, во время которой он был на грани смерти и сподобился страшного видения, полностью изменился." },
  { key: "10-16", name: "Свт. Агафангела (Преображенского), исп., митрополита Ярославского", kind: "saint", desc: "Исп. Агафангел (Преображенский, 1854–1928), митрополит Ярославский, родился в семье священника, с юности стремился к служению Церкви. Окончил Тульскую духовную семинарию и Московскую духовную академию." },
  { key: "10-16", name: "Трубчевская", year: "1765", kind: "saint", desc: "Чудотворный образ из Наровчатской Троице-Скановой обители Пензенской епархии . Обитель была знаменита своими двухкилометровыми пещерами, которые превосходили длиной знаменитые пещеры Киево-Печерской лавры." },
  { key: "10-17", name: "Сщмч. Иерофея, епископа Афинского", kind: "saint", desc: "Сщмч. Иерофей, епископ Афинский, был членом афинского ареопага и одним из первых обращенных ко Христу апостолом Павлом. Согласно церковному преданию, епископ Иерофей присутствовал при погребении Пресвятой Богородицы." },
  { key: "10-17", name: "Обретение мощей свтт. Гурия, архиепископа Казанского", kind: "saint", desc: "Свт. Гурий (в миру Григорий Руготин, †1563), первый архиепископ Казанский, происходил из радонежских дворян. В юности, оклеветанный, два года провёл в заточении, после чего принял монашество в Иосифо-Волоколамском монастыре." },
  { key: "10-17", name: "и Варсонофия, епископа Тверского", kind: "saint", desc: "Свт. Варсонофий, епископ Тверской, чудотворец Казанский, родился около 1495 года в Серпухове. В юности он 3 года провел в татарском плену, где выучил язык и обычаи." },
  { key: "10-17", name: "Собор Казанских святых", kind: "feast", desc: "17 октября Русская Православная Церковь совершает память всех угодников Божиих в земле Казанской просиявших – Собор Казанских святых. Этот праздник установлен в 1984 году по благословению святейшего патриарха Московского и всея Руси Пимена и совершается в день обретения мощей святителей Гурия и Варсонофия." },
  { key: "10-17", name: "Блгв. кн. Владимира Ярославича Новгородского, чудотворца", kind: "saint", desc: "Св. блгв. князь Владимир Ярославич (1020–1052) был старшим сыном св. Ярослава Мудрого и с 14 лет правил в Новгороде. Прославился как благочестивый христианин и защитник Отечества." },
  { key: "10-17", name: "Елладия", kind: "saint", desc: "Прп. Елладий Печерский, затворник, постник, подвизался в Киево-Печерском монастыре в XII–XIII веках. Его мощи почивают в Ближних (Антониевых) пещерах. Несмотря на скудость сведений о житии, его почитание подтверждается планом пещер 1638 года, где он указан как чудотворец." },
  { key: "10-17", name: "Онисима Печерских, в Ближних пещерах", kind: "saint", desc: "Прп. Онисим Печерский (XII-XIII вв.) ‒ затворник Киево-Печерской лавры, подвизался в Ближних пещерах, где и почивают его мощи. Преподобный Онисим Печерский (XII–XIII), подвизаясь в Киево-Печерской Лавре, затворился в Ближних пещерах (преподобного Антония)." },
  { key: "10-17", name: "прп. Аммона, затворника Печерского, в Дальних пещерах", kind: "saint", desc: "Прп. Аммон, затворник Печерский (XIII в.), именуется трудолюбивым. По благословению игумена он совершил паломничество на Афон и в Иерусалим. Вернувшись, он стал образцом благочестия и аскетизма даже для старшей братии." },
  { key: "10-17", name: "сщмч. Петра Капитолийского", kind: "saint", desc: "Сщмч. Петр Капитолийский, живший на рубеже VII–VIII веков, был пресвитером из города Капитолии. Оставив семью ради монашества, он стал ревностным проповедником христианства." },
  { key: "10-17", name: "прп. Аммона (Аммуна) Нитрийского", kind: "saint", desc: "Прп. Аммон Египетский, подвизавшийся в IV веке, вступил в брак по воле родных, но по взаимному согласию с супругой сохранил девство, живя с ней как брат с сестрой." },
  { key: "10-17", name: "прп. Павла Препростого", kind: "saint", desc: "Прп. Павел Препростый, живший в IV веке, получил свое имя за незлобие и простосердечие. В возрасте 60 лет, узнав о неверности жены, он оставил мир и пришел в пустыню к прп." },
  { key: "10-17", name: "св. Стефана Щиляновича (1515)", kind: "saint", desc: "Св. Стефан Щилянович был сербским правителем периода турецкого владычества. Он прославился защитой родины, глубоким благочестием и милосердием, раздавая хлеб во время голода." },
  { key: "10-17", name: "Николая Верещагина", kind: "saint", desc: "Сщмч. Николай Верещагин (1893–1937) был священником в селе Глебово Тверской губернии. В 1937 году его обвинили в контрреволюционной агитации за высказывания против колхозов и советской власти." },
  { key: "10-17", name: "Михаила Твердовского", kind: "saint", desc: "Сщмч. Михаил Твердовский (1881–1937) был священником в селе Загородье Калининской области. В 1937 году его арестовали по обвинению в «антисоветской агитации»." },
  { key: "10-18", name: "Мц. Харитины Амисийской (Понтийской)", kind: "saint", desc: "Мц. Харитина, жившая в конце III – начале IV века, отличалась добротой, умом и глубокой верой. Во время гонений императора Диоклетиана за исповедание христианства святая была подвергнута жестоким мучениям и скончалась в 304 году." },
  { key: "10-18", name: "свтт. Московских", kind: "saint", desc: "Собор Московских святителей – празднование Русской Православной Церкви в честь святых архипастырей Московских. Празднование в один день в честь Всероссийских святителей Петра, Алексия и Ионы установлено святым патриархом Иовом 5 октября 1596 года." },
  { key: "10-18", name: "Феогноста", kind: "saint", desc: "Свт. Феогност, грек по происхождению, возглавлял Киевскую и Владимирскую митрополию в XIV веке, сделав Москву своей резиденцией. Он был верным союзником московских князей." },
  { key: "10-18", name: "Алексия", kind: "saint", desc: "Родился в Москве в семье боярина. В 12 лет услышал голос Божий: «Алексий! Ты будешь ловить людей». Принял постриг в Богоявленском монастыре, где провёл 20 лет в подвижничестве." },
  { key: "10-18", name: "Киприана", kind: "saint", desc: "Серб (или болгарин), афонский монах. В 1375 г. поставлен митрополитом Киевским и всея Руси, управляя юго-западной частью Церкви. С 1390 г. – объединил кафедру в Москве." },
  { key: "10-18", name: "Геронтия", kind: "saint", desc: "Святитель Геронтий, митр. Московский и всея Руси († 1489) – выдающийся церковный деятель эпохи становления русского централизованного государства. Возглавлял Русскую Церковь в 1473-1489 годах." },
  { key: "10-18", name: "Иоасафа", kind: "saint", desc: "Свт. Иоасаф (Скрипицын) происходил из дворянского рода, принял постриг в Троице-Сергиевой Лавре, где стал игуменом в 1529 году. Он крестил будущего царя Ивана Грозного и постриг в монашество перед смертью его отца, великого князя Василия III." },
  { key: "10-18", name: "Макария", kind: "saint", desc: "Свт. Макарий (ок. 1482–1563) – выдающийся церковный и государственный деятель XVI века. Приняв постриг, он прошёл путь от архимандрита до митрополита Московского и всея Руси." },
  { key: "10-18", name: "Ермогена", kind: "saint", desc: "Сщмч. Ермоген (ок. 1530–1612), патриарх Московский и всея Руси, был выдающимся церковным и государственным деятелем Смутного времени. Начав служение священником в Казани, он стал свидетелем обретения Казанской иконы Божией Матери и составил службу в её честь." },
  { key: "10-18", name: "Тихона", kind: "saint", desc: "Свт. Тихон (Беллавин, 1865–1925) – одиннадцатый Патриарх Московский и всея Руси. Принял монашество в 1891 году. Управлял епархиями в Северной Америке, Ярославле, Вильно, проявляя особую заботу о пастве." },
  { key: "10-18", name: "Филарета", kind: "saint", desc: "Свт. Филарет (Дроздов, 1782–1867) ‒ один из наиболее влиятельных иерархов Русской Православной Церкви XIX века. Выпускник Троице-Сергиевой Лавры, он стал выдающимся проповедником, богословом и ректором Санкт-Петербургской духовной академии." },
  { key: "10-18", name: "Иннокентия", kind: "saint", desc: "Свт. Иннокентий (в миру Иван Попов-Вениаминов), митрополит Московский (1797-1879) – выдающийся миссионер, просветитель народов Америки и Сибири. За 45 лет он крестил десятки тысяч человек, строил храмы и школы, изучал языки, быт и нравы местных народов." },
  { key: "10-18", name: "Макария", kind: "saint", desc: "Свт. Макарий (Парвицкий-Невский, 1835–1926) – выдающийся миссионер, «Апостол Алтая». Окончив семинарию, он добровольно отправился в Алтайскую миссию, где принял монашество и посвятил 36 лет проповеди среди местных народов, изучив их язык и переведя богослужебные книги." },
  { key: "10-18", name: "прп. Харитины, кн. Литовской, в Новгороде подвизавшейся, игумении", kind: "saint", desc: "Прп. Харитина, княжна литовского происхождения, в конце XII – начале XIII века переселилась на Русь из-за смут на родине. С юности она посвятила себя Богу, приняв постриг в новгородском Петропавловском монастыре на Синичьей горе." },
  { key: "10-19", name: "Ап. Фомы", kind: "saint", desc: "Ап. Фома, рыбак из Панеады, стал одним из 12 учеников Христа. Вошёл в историю как \"неверующий\", потребовавший осязательных доказательств Воскресения. Когда Христос явился ему и показал Свои раны, Фома произнёс знаменитые слова: \"Господь мой и Бог мой!\" (Ин.20:28)." },
  { key: "10-19", name: "Св. Михаила Союзова, исп., пресвитера", kind: "saint", desc: "Исп. Михаил Союзов (1869–1922) служил псаломщиком в Андреевском соборе Кронштадта. Рукоположен в священники в 1895 году, долгое время был настоятелем церкви при 2-м Кадетском корпусе." },
  { key: "10-19", name: "сщмч. Иоанна Рыбина, пресвитера", kind: "saint", desc: "Сщмч. Иоанн Рыбин (1877–1937) родился в крестьянской семье в Самарской губернии. Рукоположен в священники в 1925 году. Неоднократно подвергался репрессиям: в 1929 году был сослан с конфискацией имущества, в 1931 и 1933 годах получал новые сроки за «невыполнение гособязательств»." },
  { key: "10-20", name: "свт. Ионы, епископа Ханькоуского", kind: "saint", desc: "Свт. Иона (Покровский, 1888–1925) – епископ Ханькоуский, выдающийся пастырь Русского Зарубежья. Окончил Казанскую духовную академию, принял монашество." },
  { key: "10-20", name: "Прп. Сергия Послушливого, Печерского, в Ближних пещерах", kind: "saint", desc: "Прп. Сергий Послушливый (или Послушный) подвизался, предположительно, в XII–XIII веках в Киево-Печерской лавре в Ближних (Антониевых) пещерах. Точных сведений о нём не сохранилось." },
  { key: "10-20", name: "прп. Сергия Нуромского (Вологодского)", kind: "saint", desc: "Прп. Сергий Нуромский (Обнорский) – постриженик Афонской Горы, ученик прп. Сергия Радонежского. Стремясь к безмолвию, он удалился в дикие леса на реку Нурму, где терпеливо переносил лишения и нападения." },
  { key: "10-20", name: "прп. Мартиниана Белоезерского, игумена", kind: "saint", desc: "Прп. Мартиниан Белозерский (ок. 1397–1483) – ученик прп. Кирилла Белозерского. В 13 лет пришел в его монастырь, где научился грамоте и переписыванию книг." },
  { key: "10-20", name: "мц. Пелагии Тарсийской", kind: "saint", desc: "Св. мц. Пелагия Тарсийская, знатная и образованная девушка из Малой Азии, жила в конце III века. Пленившись красотой, император Диоклетиан хотел выдать её замуж за своего наследника." },
  { key: "10-20", name: "сщмч. Полихрония, пресвитера", kind: "saint", desc: "Сщмч. Полихроний, сын земледельца, с юности отличался трудолюбием и благочестием. Перебравшись в Константинополь, он работал на винограднике, а на заработанные деньги построил храм." },
  { key: "10-20", name: "Сщмч. Николая Казанского, пресвитера", kind: "saint", desc: "Сщмч. Николай Казанский (1874–1942) – протоиерей, служивший в Таврической губернии. После революции неоднократно арестовывался за сопротивление изъятию церковных ценностей и борьбу с обновленчеством." },
  { key: "10-20", name: "Умиление Псково-Печерская", year: "1524", kind: "saint", desc: "По преданию, Псково-Печерская икона Божией Матери «Умиление» была написана в 1521 году неким иеромонахом Арсением (Хитрошем) с иконы Божией Матери «Владимирская»." },
  { key: "10-21", name: "Прп. Пелагии Антиохийской", kind: "saint", desc: "Прп. Пелагия Антиохийская до своего обращения ко Христу была легкомысленной и распущенной девицей, но проповедь святителя Нонна привела её к глубокому покаянию." },
  { key: "10-21", name: "Прп. Досифея Верхнеостровского, Псковского, игумена", kind: "saint", desc: "Прп. Досифей Верхнеостровский (Псковский) был учеником прп. Евфросина Псковского. В 1470 году он основал Петропавловский Верхнеостровский монастырь на одном из островов Псковского озера и стал его первым игуменом." },
  { key: "10-21", name: "прп. Трифона, архимандрита Вятского", kind: "saint", desc: "Прп. Трифон Вятский (XVI–XVII вв.) с юности стремился к монашеству, принял постриг в Пыскорском монастыре. Обращал в христианство языческие народы (остяков и вогулов) в Пермском крае." },
  { key: "10-21", name: "Собор Вятских святых", kind: "feast", desc: "Прославление Собора Вятских святых состоялось в связи с празднованием 350-летия Вятской епархии в день памяти преподобного Трифона Вятского, 21 октября 2007 года, в Успенском кафедральном соборе Трифонова мужского монастыря митрополитом Вятским Хрисанфом." },
  { key: "10-21", name: "прп. Таисии Египетской", kind: "saint", desc: "Св. Таисия Египетская (III–IV вв.) была знаменитой блудницей, чья красота доводила многих мужей до разорения. Её обращение совершил старец Пафнутий Великий, который, придя к ней, убедил её в том, что Бог видит все её грехи." },
  { key: "10-21", name: "мц. Пелагии девицы, Антиохийской", kind: "saint", desc: "Св. Пелагия Антиохийская (III в.) была знатной и красивой христианкой. Когда воины правителя города пришли арестовать её, она, опасаясь надругательства и желая сохранить девство, посвящённое Богу, взмолилась о помощи." },
  { key: "10-21", name: "Димитрия (Добросердова), архиепископа Можайского, и с ним", kind: "saint", desc: "Сщмч. Димитрий (Добросердов, 1864–1937), архиепископ, принял монашество после смерти семьи. В 1920-е годы активно противостоял обновленческому расколу, возглавляя Тамбовскую и Пятигорскую епархии, где вернул большинство приходов в лоно Патриаршей Церкви." },
  { key: "10-21", name: "Иоанна Хренова, диакона", kind: "saint", desc: "Сщмч. Иоанн Хренов (1888–1937), диакон, родился в Москве в благочестивой семье. Окончив педагогический институт, работал бухгалтером. В 1921 году был рукоположен в диакона, служил в московских храмах." },
  { key: "10-21", name: "Амвросия (Астахова), архимандрита", kind: "saint", desc: "Прмч. Амвросий (Астахов, 1860–1937) родился в крестьянской семье в Тамбовской губернии. До 1925 года жил в монастыре, а после его закрытия поселился в селе Аксиньино Московской области, продолжая духовно окормлять монахинь и мирян." },
  { key: "10-21", name: "Пахомия (Туркевича), игумена", kind: "saint", desc: "Прмч. Пахомий (Туркевич, 1864–1937), игумен, родился на Волыни в семье кузнеца. Подвизался в Златоустовском монастыре до его закрытия в 1923 году. В конце 20-х – начале 30-х годов, будучи в преклонных летах, жил в Москве у своих духовных детей." },
  { key: "10-21", name: "сщмч. Ионы (Лазарева), епископа Велижского", kind: "saint", desc: "Сщмч. Иона (Лазарев) родился в 1869 году в семье священника. Окончив Новгородскую духовную семинарию, он принял монашество и прошёл путь от иеродиакона до архимандрита." },
  { key: "10-21", name: "прмч. Серафима (Щелокова), архимандрита", kind: "saint", desc: "Прмч. Серафим (Щелоков) родился в 1877 году. Приняв монашество, он служил в нескольких монастырях. В 1931 году был арестован за антисоветскую деятельность и после отказа стать осведомителем ОГПУ сослан на три года." },
  { key: "10-21", name: "Петра Никотина", kind: "saint", desc: "Сщмч. Петр Никотин родился в 1889 году, окончил Казанскую духовную академию. Служил священником в московских храмах, в том числе в церкви прп. Сергия на Рогожской заставе." },
  { key: "10-21", name: "Василия Озерецковского", kind: "saint", desc: "Сщмч. Василий Озерецковский, священник, родился в 1885 году. Окончив Московскую духовную семинарию, он служил псаломщиком, а в 1920 году был рукоположен в сан священника." },
  { key: "10-22", name: "Ап. Иакова Алфеева", kind: "saint", desc: "Ап. Иаков Алфеев, брат евангелиста Матфея, был призван Христом в число 12 учеников. После Пятидесятницы проповедовал в Иудее, затем вместе с ап. Андреем Первозванным ‒ в Едессе." },
  { key: "10-22", name: "св. Поплии исп., диаконисы Антиохийской", kind: "saint", desc: "Исповедница Поплия, Антиохийская диаконисса, рано овдовев, посвятила себя воспитанию сына и служению Богу. Она основала в своем доме общину для вдов и дев, желающих посвятить жизнь христианскому подвигу." },
  { key: "10-22", name: "прп. Петра Галатийского", kind: "saint", desc: "Прп. Петр, в миру Леонтий, родился в Галатии в правление императора-иконоборца Феофила. Обладая величественной внешностью и большой силой, он был назначен в царские комиты (спутники), но вскоре оставил службу, приняв монашеский постриг в Дафнеонском монастыре." },
  { key: "10-22", name: "Константина Сухова", kind: "saint", desc: "Сщмч. Константин Сухов родился в 1867 году. Окончив Симбирскую духовную семинарию, он служил священником в селах Самарской епархии. С 1903 года был настоятелем Спасо-Вознесенского собора в Бугуруслане, активно занимался просвещением и общественной деятельностью в земстве." },
  { key: "10-22", name: "Петра Вяткина", kind: "saint", desc: "Сщмч. Петр Вяткин родился в 1882 году в крестьянской семье. Окончив земское училище, он в 1904 году начал служение псаломщиком, а в 1908 году был рукоположен в священника единоверческой церкви." },
  { key: "10-22", name: "сщмч. Константина Аксёнова, пресвитера", kind: "saint", desc: "Сщмч. Константин Аксёнов родился в 1888 году в Ташкенте. Неоднократно подвергался репрессиям: в 1923 году был приговорен к 3 годам концлагерей, а в 1929 году ‒ к 3 годам ссылки в Северный край." },
  { key: "10-22", name: "Обретение мощей прп. Севастиана Карагандинского (Фомина), исп., схиархимандрита", kind: "saint", desc: "Прписп. Севастиан (Фомин) родился в 1884 году. Рано осиротев, он в 1909 году стал келейником прп. Иосифа в Оптиной пустыни, а после его кончины ‒ келейником прп." },
  { key: "10-22", name: "Корсунская", kind: "saint", desc: "Существуют два разных предания, касающихся истории принесения в пределы России Корсунской иконы Божией Матери. Согласно самому древнему из них, святой образ был написан святым евангелистом Лукой и хранился в Ефесе." },
  { key: "10-23", name: "свт. Иннокентия (Смирнова), епископа Пензенского", kind: "saint", desc: "Свт. Иннокентий (Смирнов), епископ Пензенский (1784–1819), был известным учёным-богословом и профессором Санкт-Петербургской Духовной Академии. Его главный труд «Начертание церковной истории» на протяжении полувека служил руководством в духовных школах." },
  { key: "10-23", name: "прп. Амвросия Оптинского", kind: "saint", desc: "Прп. Амвросий Оптинский (1812-1891) ‒ великий русский старец, святость и богоугодность жития которого Бог засвидетельствовал многими чудесами. Родившись в семье пономаря, он после тяжелой болезни исполнил обет и поступил в Оптину пустынь (1839 г.).", lifeId: "amvrosiy-optinsky" },
  { key: "10-23", name: "Свт. Амфилохия, епископа Владимиро-Волынского", kind: "saint", desc: "Свт. Амфилохий, епископ Владимиро-Волынский, был поставлен на кафедру в 1105 году и 17 лет управлял паствой в сложный период княжеских междоусобиц. Он активно проповедовал Христа среди язычников и боролся с суевериями." },
  { key: "10-23", name: "Собор Волынских святых", kind: "feast", desc: "Празднование совершается в воспоминание о воссоединении Почаевской Лавры из унии в православие 10 октября 1831 года. Великими и знаменательными чертами запечатлена история православной церкви на Волыни." },
  { key: "10-23", name: "блж. Андрея, Христа ради юродивого, Тотемского", kind: "saint", desc: "Блж. Андрей Тотемский (1638-1673) принял подвиг юродства Христа ради. Поселившись в Тотьме у церкви Воскресения Христова, он круглый год ходил босиком в рубище, питаясь лишь хлебом и водой." },
  { key: "10-23", name: "мч. Феотекна Антиохийского", kind: "saint", desc: "Св. мученик Феотекн, военачальник в Антиохии, пострадал за Христа при императоре Максимиане (305-311). Отказавшись принести жертву идолам, он был подвергнут унижениям и жестоким пыткам, включая пытку огнем и кипящей смолой, но чудесным образом остался невредим." },
  { key: "10-23", name: "прп. Вассиана (Василия) Константинопольского, игумена", kind: "saint", desc: "Прп. Вассиан, уроженец восточной Сирии, подвизался в Константинополе при императоре Маркиане (450–457). Он был игуменом обители, в которой насчитывалось около трехсот иноков." },
  { key: "10-23", name: "прп. Феофила Тивериопольского, исп.", kind: "saint", desc: "Прп. Феофил исповедник в юности ушел в Лавру на Селентийской горе, где принял постриг. По воле Божией, явленной через глас в храме, он основал новую обитель близ родного Тивериополя." },
  { key: "10-24", name: "Ап. от 70-ти Филиппа, единого от семи диаконов", kind: "saint", desc: "Св. апостол от 70-ти Филипп, один из семи первых диаконов, был поставлен апостолами для служения в Иерусалимской Церкви. После мученической смерти архидиакона Стефана он проповедовал в Самарии, где обратил многих, включая волхва Симона." },
  { key: "10-24", name: "прп. Феофана исп., творца канонов, епископа Никейского", kind: "saint", desc: "Прпп. Феодор и Феофан Начертанные, братья из Иерусалима, стали монахами в Лавре святого Саввы. При императорах-иконоборцах Льве V Армянине, Михаиле II и Феофиле их неоднократно ссылали за твердую защиту иконопочитания." },
  { key: "10-24", name: "прп. Льва Оптинского", kind: "saint", desc: "Прп. Лев Оптинский (1768–1841), в миру Лев Наголкин – основатель старчества в Оптиной пустыни. Нёс подвиг духовного руководства, отличался даром прозорливости и чудотворений." },
  { key: "10-24", name: "Собор всех святых, в Оптиной пустыни просиявших", kind: "feast", desc: "Единая память просиявших в Оптиной пустыни преподобных, мучеников и исповедников установлена в день празднования Собора преподобных Оптинских старцев (11/24 октября) по благословению Святейшего Патриарха Кирилла от 27 октября 2016 года." },
  { key: "10-24", name: "Прп. Феофана, постника Печерского, в Ближних пещерах", kind: "saint", desc: "Прп. Феофан постник достиг духовного совершенства через суровый пост. Его святые мощи почивают в Антониевой пещере Киево-Печерской лавры. Прозвание Постник, с которым известен преподобный Феофан, указывает, что строгий пост был тем путем, которым он приблизился к Господу." },
  { key: "10-24", name: "Филарета Великанова", kind: "saint", desc: "Сщмч. Филарет Великанов родился в 1873 году в семье диакона. Окончив Пензенскую духовную семинарию, он служил псаломщиком, диаконом, а в 1916 году был рукоположен во священника и назначен экономом Казанской духовной академии." },
  { key: "10-24", name: "Александра Гривского", kind: "saint", desc: "Сщмч. Александр Гривский (1874–1918) родился в семье священника и окончил Псковскую духовную семинарию. Служил священником в селе Подоклинье Порховского уезда." },
  { key: "10-25", name: "прп. Космы, епископа Маиумского, творца канонов", kind: "saint", desc: "Прп. Косма Маиумский, творец канонов, был сподвижником прп. Иоанна Дамаскина и получил вместе с ним прекрасное образование. Прославился как активный защитник иконопочитания, написав множество сочинений против иконоборцев." },
  { key: "10-25", name: "Прп. Амфилохия, игумена Глушицкого", kind: "saint", desc: "Прп. Амфилохий Глушицкий начал иноческий путь в Устюге Великом, а в 1417 году стал учеником и сподвижником прп. Дионисия Глушицкого, подражая его кротости и терпению." },
  { key: "10-25", name: "мц. Домники (Домнины)", kind: "saint", desc: "Св. мученица Домника жила в Киликийской области и пострадала за веру во Христа в 286 году. По приказу правителя её подвергли жестоким истязаниям: били и жгли огнём." },
  { key: "10-25", name: "свт. Мартина Милостивого, епископа Турского", kind: "saint", desc: "Свт. Мартин Милостивый, епископ Турский, первоначально был военачальником при императоре Юлиане Отступнике. Одержав победу над варварами, он отказался приносить жертву идолам и удалился в монастырь." },
  { key: "10-25", name: "Перенесение из Мальты в Гатчину части Древа Животворящего Креста Господня, Филермской иконы Божией Матери и десной руки Иоанна Крестителя", year: "1799", kind: "icon", desc: "Перенесение из Мальты в Гатчину части древа Животворящего Креста Господня, Филермской иконы Божией Матери и десной руки святого Иоанна Крестителя совершилось в 1799 году." },
  { key: "10-25", name: "Св. Иоанна Летникова, исп.", kind: "saint", desc: "Исп. Иоанн Летников (1860–1930) родился в Московской губернии. Был лесопромышленником и владельцем завода, который после революции передал государству." },
  { key: "10-25", name: "прмч. Лаврентия (Левченко), иеромонаха", kind: "saint", desc: "Прмч. Лаврентий (Левченко) родился в 1893 году в Томской губернии. В 1910 году поступил в Оптину Пустынь, где был пострижен в монашество, рукоположен во иеродиакона и возведен в сан архидиакона." },
  { key: "10-25", name: "сщмч. Александра Поздеевского, пресвитера", kind: "saint", desc: "Сщмч. Александр Поздеевский (1868–1940) был священником в селе Большие Соли Костромской губернии. После закрытия храма в 1930 году он продолжал тайно обучать детей Закону Божьему и участвовал в богослужениях в домашней молельне." },
  { key: "10-25", name: "свт. Николая (Могилевского), исп., митрополита Алма-Атинского", kind: "saint", desc: "Сщисп. Николай (Могилевский, 1877–1955) прошёл многолетние тюремные заключения и ссылки в 1920–1940-х годах, сохранив верность пастырскому служению. В 1945 году назначен архиепископом Алма-Атинским и Казахстанским." },
  { key: "10-25", name: "Иерусалимская", year: "48", kind: "saint", desc: "Иерусалимская икона Божией Матери, по преданию, написана святым евангелистом Лукой в 15-й год после Вознесения Господа в Гефсимании (48). В 463 году образ был перенесен греческим царем Львом Великим в Константинополь." },
  { key: "10-25", name: "Одигитрия Ярославская", year: "1642", kind: "saint", desc: "Ярославско-Смоленская икона Божией Матери - келейный образ архимандрита Троице-Сергиевой Лавры Антония. 12 октября 1642 года во время молитвы он услышал от иконы - Смоленской Одигитрии - голос: &quot;Иду, иду в пределы града Ярославля, в новосозданный монастырь во Имя Мое&quot;." },
  { key: "10-25", name: "Рудненская (Руденская)", year: "1687", kind: "saint", desc: "Чудотворная Рудненская икона Божией Матери была явлена в 1687 году в местечке Рудня Могилевской епархии. В 1689 году местным иереем отцом Василием она была перенесена в Киево-Печерский женский монастырь." },
  { key: "10-25", name: "Калужская", kind: "saint", desc: "Явление Калужской иконы Божией Матери произошло в 1748 году в селе Тинькове, недалеко от Калуги, в доме помещика Василия Кондратьевича Хитрово. Две служанки перебирали на чердаке его дома старые вещи." },
  { key: "10-26", name: "Иверской иконы Божией Матери", kind: "icon", desc: "Иверская икона Божией Матери, находящаяся на Афоне , прославилась многими чудесами. Слух о чудотворном образе через паломников распространился по России." },
  { key: "10-26", name: "Прп. Вениамина Печерского, в Дальних пещерах", kind: "saint", desc: "Прп. Вениамин Печерский, живший в XIV веке, до монашества был богатым купцом. Под впечатлением от евангельских слов о трудности вхождения богатых в Царство Небесное, он раздал всё своё имение нищим и храмам." },
  { key: "10-26", name: "мч. Флорентия Солунянина", kind: "saint", desc: "Св. мученик Флорентий (II век), уроженец Солуни, ревностно проповедовал христианство, обличая язычество и обращая многих ко Христу. За свою проповедь он был схвачен язычниками, подвергнут жестоким мучениям и сожжен." },
  { key: "10-26", name: "сщмч. Вениамина, диакона", kind: "saint", desc: "Сщмч. Вениамин Персидский пострадал за Христа в V веке. Будучи диаконом, он обратил в христианство многих персов-язычников. После двух лет заключения его освободили при условии прекращения проповеди, но он продолжил своё дело." },
  { key: "10-26", name: "прп. Никиты Исповедника, Константинопольского", kind: "saint", desc: "Прп. Никита Исповедник, живший в VIII-IX веках, первоначально служил при дворе императрицы Ирины. Оставив мирские почести, он принял монашество. Когда к власти пришел император-иконоборец Феофил, прп." },
  { key: "10-26", name: "свт. Мелетия (Пигаса), патриарха Александрийского", kind: "saint", desc: "Свт. Мелетий (Пигас, 1549–1601), патриарх Александрийский, родился на Крите. Получив образование в Италии, он принял монашество. Став патриархом в 1590 году, решал проблемы долгов патриархата перед султаном и активно противостоял прозелитизму иезуитов." },
  { key: "10-26", name: "вмц. Златы (Хрисы) в Скопье", kind: "saint", desc: "Вмц. Злата Могленская († 1795) ‒ болгарская святая, пострадавшая за веру во Христа во времена османского владычества. Отличалась красотой, целомудрием и твёрдостью веры." },
  { key: "10-26", name: "Обретение мощей сщмч. Фаддея (Успенского), архиепископа Тверского", kind: "saint", desc: "Сщмч. Фаддей (Успенский, 1872–1937), архиепископ Тверской, был выдающимся церковным деятелем. Получив образование в Московской Духовной Академии, принял монашество." },
  { key: "10-26", name: "Одигитрия Седмиезерная", year: "XVII", kind: "saint", desc: "Седмиезерная икона принадлежит к числу икон, пользующихся чрезвычайным почитанием в местах ее нахождения. День празднования в честь нее является торжеством не только для Седмиезерной пустыни и Казани, но и для всего Прикамского Поволжья." },
  { key: "10-27", name: "прп. Параскевы-Петки Сербской", kind: "saint", desc: "Прп. Параскева Сербская родилась в благочестивой семье. После смерти отца она вместе с братом, свт. Евфимием, оставила дом для подвижнической жизни. Сначала она отправилась в Константинополь, а затем долгие годы провела в Иорданской пустыне." },
  { key: "10-27", name: "Прп. Николы Святоши, кн. Черниговского, Печерского чудотворца, в Ближних пещерах", kind: "saint", desc: "Прп. Никола Святоша (Святослав), князь Черниговский († 1143), был правнуком блгв. кн. Ярослава Мудрого. В 1106 году, оставив семью и княжение, он принял постриг в Киево-Печерской лавре, став первым русским князем-иноком." },
  { key: "10-27", name: "сщмч. Сильвана, пресвитера Газского", kind: "saint", desc: "Сщмч. Сильван, епископ Газский, происходил из окрестностей Газы. Будучи в миру воином, он принял священство, а затем был рукоположен во епископа и обратил многих язычников в христианство." },
  { key: "10-27", name: "Сщмч. Михаила Лекторского, пресвитера", kind: "saint", desc: "Сщмч. Михаил Лекторский (1872–1921) был протоиереем на Кубани, служил в станице Новотитаровской. В сентябре 1921 года он был арестован по обвинению в контрреволюционной агитации и заключён в станице Брюховецкой." },
  { key: "10-27", name: "свт. Амвросия (Полянского), исп., епископа Каменец-Подольского", kind: "saint", desc: "Сщисп. Амвросий (Полянский, 1878–1932) был епископом Каменец-Подольским. После революции мужественно противостоял обновленческому расколу, за что неоднократно подвергался арестам и гонениям." },
  { key: "10-27", name: "сщмч. Петра Лебедева, пресвитера", kind: "saint", desc: "Сщмч. протоиерей Петр Лебедев служил в Ильинском храме села Родники Ивановской области. Известный своим бескорыстием, аскетизмом и твердой верой, он активно противостоял обновленчеству и богоборческой власти после 1917 года." },
  { key: "10-27", name: "прмч. Максимилиана (Марченко), игумена", kind: "saint", desc: "Прмч. игумен Максимилиан (Марченко), выходец из казачьей семьи, принял постриг в Троице-Сергиевой Лавре. Во время Первой мировой войны служил священником в армейском лазарете." },
  { key: "10-27", name: "Яхромская", year: "XV", kind: "saint", desc: "Яхромская икона Божией Матери [1] явилась отроку Косме (память 18 февраля), сопровождавшему больного. Косма остановился на берегу реки Яхромы, недалеко от Владимира, и больной уснул." },
  { key: "10-28", name: "Прп. Евфимия Нового, Солунского, иеродиакона", kind: "saint", desc: "Прп. Евфимий Новый, Солунский (IX в.), в миру Никита, родился в Анкире Галатийской. После воинской службы и краткого брака тайно ушёл в монастырь. Подвизался 15 лет на горе Олимп, затем на Афоне, где принял великую схиму и три года провёл в полном безмолвии в пещере." },
  { key: "10-28", name: "прмч. Лукиана, пресвитера Антиохийского", kind: "saint", desc: "Прмч. Лукиан, пресвитер Антиохийский, родился в Самосате. Рано осиротев, раздал имущество и стал учеником исповедника Макария в Эдессе. За благочестие был рукоположен в пресвитеры." },
  { key: "10-28", name: "свт. Афанасия (Сахарова) исп., епископа Ковровского", kind: "saint", desc: "Свт. Афанасий (Сахаров) родился в 1887 году во Владимире. Окончил Московскую духовную академию, стал специалистом по литургике. Принял монашество в 1912 году." },
  { key: "10-28", name: "Свт. Иоанна, епископа Суздальского", kind: "saint", desc: "Свт. Иоанн с юности принял монашество. В 1350 году за добродетельную жизнь он был поставлен первым епископом Суздальским и Нижегородским. Святитель удостоился великой милости Божией: во время Божественной литургии Суздальский князь Борис Константинович видел, как Ангел сослужил ему." },
  { key: "10-28", name: "сщмч. Лукиана Печерского, в Дальних пещерах, пресвитера", kind: "saint", desc: "Сщмч. Лукиан пострадал от хана Батыя около 1243 года. Сведения о его жизни известны лишь из надписи на древней доске с иконой святого. Его мощи почивают в Дальних (Феодосиевых) пещерах Киево-Печерской лавры." },
  { key: "10-28", name: "свт. Савина, епископа Катанского", kind: "saint", desc: "Свт. Савин был епископом Катаны в Сицилии. Стремясь усерднее служить Богу, он удалился в пустыню, где удостоился дара чудотворения и прозорливости. Святитель Савин, епископ города Катаны в Сицилии, желая усерднее послужить Господу, удалился в пустыню." },
  { key: "10-28", name: "Сщмч. Симеона Конюхова, пресвитера", kind: "saint", desc: "Сщмч. Симеон Конюхов родился в 1853 году. Рукоположен в священника в 1877 году. С 1916 года служил в единоверческой церкви села Воробьево (Воробьи) Пермской губернии." },
  { key: "10-28", name: "сщмч. Димитрия Касаткина, пресвитера", kind: "saint", desc: "Сщмч. Димитрий Касаткин (1884–1942) 20 лет служил в храме погоста Гвоздня Московской губернии. В 1930-х годах активно препятствовал закрытию храма. Был арестован в 1937 году по обвинению в антиколхозной агитации и контрреволюционной деятельности." },
  { key: "10-28", name: "Спорительница хлебов", year: "XIX", kind: "saint", desc: "Икона Божией Матери, именуемая &quot;Спорительница хлебов&quot;, написана по благословению старца Введенской Оптиной пустыни иеросхимонаха Амвросия (23.XI.1812 - 10.X.1891)." },
  { key: "10-29", name: "Мч. Лонгина Сотника, иже при Кресте Господни", kind: "saint", desc: "Мч. Лонгин был римским воином из Каппадокии, стоявшим на страже у Креста Господня и Гроба. Он стал свидетелем страданий, смерти и Воскресения Христа, а также сопровождавших их чудес, что привело его к вере." },
  { key: "10-29", name: "Прп. Лонгина, вратаря Печерского, в Дальних пещерах", kind: "saint", desc: "Прп. Лонгин подвизался в Киево-Печерском монастыре в XIII-XIV веках. Он нёс обязанности привратника и прославился своим великим послушанием и святостью жизни." },
  { key: "10-29", name: "прп. Лонгина Яренгского", kind: "saint", desc: "Прпп. Иоанн и Лонгин Яренгские были иноками Соловецкого монастыря в XVI веке, подвизавшимися под руководством игумена Филиппа (впоследствии митрополита Московского)." },
  { key: "10-29", name: "Обретение мощей свт. Иоанна (Максимовича), митрополита Тобольского", kind: "saint", desc: "Свт. Иоанн Тобольский (1651-1715), в миру Иоанн Максимович, родился в Нежине. Окончив Киево-Могилянскую коллегию, принял монашество в Киево-Печерской лавре." },
  { key: "10-29", name: "прп. Галла", kind: "saint", desc: "Прп. Галл, ирландский священник и сподвижник св. Колумбана, прибыл в Швейцарию около 610 года для проповеди. Став отшельником у источников Штейнбах, он, по преданию, приручил медведя." },
  { key: "10-29", name: "Св. Георгия Троицкого, исп., пресвитера", kind: "saint", desc: "Сщисп. Георгий Троицкий (1873–1931) был священником, служившим в Спасском храме села Рай-Семеновское Московской губернии с 1903 года. В 1930 году, после того как он проинформировал прихожан о слухах о закрытии храма и высоких налогах, его обвинили в антисоветской агитации.", lifeId: "georgiy" },
  { key: "10-29", name: "сщмч. Евгения Елховского, пресвитера", kind: "saint", desc: "Сщмч. Евгений Елховский (1869–1937) окончил Владимирскую духовную семинарию. Рукоположен в священника в 1895 году и служил в храмах Переславля-Залесского, был законоучителем." },
  { key: "10-29", name: "сщмч. Алексия Никонова, пресвитера", kind: "icon", desc: "Сщмч. Алексий Никонов (1881–1938) окончил Московскую духовную академию. После службы в армии и учительствования был рукоположен в священника в 1922 году." },
  { key: "10-29", name: "сщмч. Иоанна Заседателева, пресвитера", kind: "saint", desc: "Сщмч. Иоанн Заседателев (1867–1942) родился в старообрядческой семье, но в 1885 году присоединился к Православной Церкви и стал активным миссионером. Рукоположен в священника в 1896 году, долгие годы служил в единоверческих храмах Самарской губернии." },
  { key: "10-30", name: "Прор. Осии", kind: "saint", desc: "Св. пророк Осия жил в VIII веке до Р.Х. в Израильском царстве. Он был современником пророков Исаии, Михея и Амоса. Его пророческое служение длилось более 60 лет и было направлено на обличение идолопоклонства и беззаконий соплеменников, предсказание их плена и последующего обращения к Богу." },
  { key: "10-30", name: "прмч. Андрея Критского", kind: "saint", desc: "Прмч. Андрей Критский жил в VIII веке при императоре-иконоборце Константине Копрониме. Он публично обличил правителя в гонениях на веру, утверждая, что почитание иконы есть почитание Самого Христа." },
  { key: "10-30", name: "Прп. Антония Леохновского, Новгородского, игумена", kind: "saint", desc: "Прп. Антоний Леохновский, происходивший из боярского рода, был новгородским пустынножителем. Около 1556 года он основал Спасо-Преображенскую пустынь на Леохнове, близ Старой Руссы." },
  { key: "10-30", name: "Перенесение мощей прав. Лазаря Четверодневного, епископа Китийского", kind: "saint", desc: "Св. праведный Лазарь, друг Христов, жил в Вифании с сёстрами Марфой и Марией. Господь Иисус Христос воскресил его из мёртвых на четвертый день после погребения, что стало величайшим чудом." },
  { key: "10-30", name: "Сщмчч. Неофита Любимова", kind: "saint", desc: "Сщмч. Неофит Любимов (1846–1918) был образованным пастырем, выпускником Киевской Духовной академии. Более 30 лет служил священником, совмещая это с преподаванием в учебных заведениях Симбирска." },
  { key: "10-30", name: "Анатолия Ивановского, пресвитеров", kind: "saint", desc: "Сщмч. Анатолий Ивановский (1863–1918) окончил Вятскую духовную семинарию. В 1901 году рукоположен во священника и 17 лет служил в Казанско-Богородицкой церкви села Салтак-Ял, совмещая пастырское служение с работой законоучителя." },
  { key: "10-30", name: "прмчч. Иакинфа", kind: "saint", desc: "Прмч. Иакинф (Питателев) родился в 1882 году в Пермской губернии. В 1912 году поступил в Верхотурский Николаевский монастырь, где в 1917 году принял постриг." },
  { key: "10-30", name: "Каллиста (Опарина), монахов", kind: "saint", desc: "Прмч. Каллист (Опарин) родился в 1864 году. В 1899 году поступил в Верхотурский Николаевский монастырь, где принял монашеский постриг. После революции, в октябре 1918 года, он вместе с монахом Иакинфом (Питателевым) был оставлен для охраны Мало-Актайского скита от грабежа." },
  { key: "10-30", name: "сщмч. Александра (Щукина), архиепископа Семипалатинского", kind: "saint", desc: "Сщмч. Александр (Щукин), архиепископ Семипалатинский, родился в 1891 году в Риге. Окончил Московскую Духовную академию, принял монашеский постриг. В 1923 году хиротонисан во епископа Лысковского, викария Нижегородской епархии." },
  { key: "10-30", name: "Прежде Рождества и по Рождестве Дева", year: "1827", kind: "saint", desc: "Икона Божией Матери, именуемая &quot;Прежде Рождества и по Рождестве Дева&quot;, принесена в Николаевский Пешношский монастырь Московской епархии московским купцом Алексеем Григорьевичем Мокеевым." },
  { key: "10-30", name: "Избавительница", kind: "saint", desc: "Икона Божией Матери «Избавительница» до 20 июля 1889 года, когда она была принесена в Ново-Афонский Симоно-Кананитский монастырь на Кавказе, находилась на Святой Горе Афон у насельника Русского Пантелеимонова монастыря схимонаха Мартиниана (&dagger; 1884)." },
  { key: "10-31", name: "Апостола и евангелиста Луки", kind: "saint", desc: "Св. апостол и евангелист Лука, сподвижник апостола Павла, был врачом из Антиохии. Он принадлежал к числу 70 учеников Христа и является автором третьего Евангелия и книги Деяний апостолов." },
  { key: "10-31", name: "Обретение мощей прп. Иосифа, игумена Волоцкого, чудотворца", kind: "saint", desc: "Прп. Иосиф Волоцкий (Санин, 1439/40–1515) – великий русский святой, основатель Иосифо-Волоколамского монастыря и строгого общежительного устава. Ученик прп." },
  { key: "10-31", name: "Мч. Марина Аназаровского", kind: "saint", desc: "Св. мученик Марин, родом из Киликии, пострадал за веру во Христа в период правления императора Диоклитиана (284–305 гг.). По приказу правителя Тарса Лисия он был подвергнут жестоким пыткам и затем казнен." },
  { key: "10-31", name: "прп. Иулиана Персиянина", kind: "saint", desc: "Прп. Иулиан подвизался в Месопотамии. Во время молитвы он получил откровение о скорой гибели императора-отступника Юлиана, которое вскоре сбылось. Однажды во время молитвы преподобный услышал глас, возвестивший, что император Юлиан Отступник скоро погибнет." },
  { key: "10-31", name: "вмц. Златы (Хрисы) (1795)", kind: "saint", desc: "Вмц. Злата Могленская († 1795) ‒ болгарская святая, пострадавшая за веру во Христа во времена османского владычества. Отличалась красотой, целомудрием и твёрдостью веры." },
  { key: "10-31", name: "Сщмч. Димитрия Вознесенского, пресвитера", kind: "saint", desc: "Сщмч. Димитрий Вознесенский (1855–1918) был священником в селе Николо-Замошье. В 1918 году, после крестного хода и молебна, он произнес проповедь, обличавшую богоборческую политику большевиков." },
  { key: "10-31", name: "Андрея Воскресенского", kind: "saint", desc: "Сщмч. Андрей Воскресенский (1884–1937) окончил Московскую духовную академию, в 1912 году рукоположен во священника. Служил в московских храмах, затем в церкви села Карпово Московской области, где был любим прихожанами за доброту и помощь." },
  { key: "10-31", name: "Сергия Бажанова", kind: "saint", desc: "Сщмч. Сергий Бажанов (1883–1937) служил в храмах Коломенского уезда. В 1930 году впервые арестован по обвинению в антисоветской агитации и срыве колхозного строительства, приговорен к 3 годам лагерей на строительстве Беломорканала." },
  { key: "10-31", name: "Николая Соколова", kind: "saint", desc: "Сщмч. Николай Соколов (1877–1937) окончил Московскую духовную семинарию. Долгие годы служил в Преображенском храме села Крымское, совмещая пастырское служение с преподаванием Закона Божия." },
  { key: "10-31", name: "Сергия Гусева", kind: "saint", desc: "Сщмч. Сергий Гусев (1886–1937) окончил иконописное училище, работал учителем. После службы в Красной армии стал псаломщиком, в 1922 году рукоположен в диакона, а в 1934 году – в священника." },
  { key: "10-31", name: "мц. Елисаветы Крымовой", kind: "saint", desc: "Мц. Елисавета Крымова (1877–1937) родилась в Серпухове в бедной семье, воспитывалась в приюте. Всю жизнь была глубоко верующей, поддерживала связи с монахинями Владычнего монастыря." },
];
